"""Rich, dependency-free frontend layout for bounded local-model copy generation."""

def render(title, headline, description, cards):
    page = r'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>
:root{--ink:#182921;--muted:#637168;--paper:#faf9f3;--accent:#d8ef82;--peach:#f2c7ac;--line:#dde2d7}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}button,input,select{font:inherit}button,a,input,select{-webkit-tap-highlight-color:transparent}a{color:inherit}button,a{touch-action:manipulation}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #578249;outline-offset:4px}button{cursor:pointer}h1,h2,h3,p{margin-top:0}h1{font-size:clamp(42px,5.7vw,76px);line-height:1.05;letter-spacing:-.065em;margin:22px 0}h2{font-size:clamp(30px,4vw,46px);line-height:1.15;letter-spacing:-.045em}h3{font-size:20px;line-height:1.3}.wrap{max-width:1180px;margin:auto;padding:0 28px}nav{display:flex;align-items:center;justify-content:space-between;gap:22px;padding:24px 0;border-bottom:1px solid var(--line)}.brand{font-weight:800;letter-spacing:-.04em;font-size:22px;text-decoration:none;overflow-wrap:anywhere}.brand i{display:inline-grid;place-items:center;width:30px;height:30px;background:var(--ink);color:var(--accent);border-radius:8px;font-style:normal;margin-right:8px}.links{display:flex;gap:22px;align-items:center;font-size:14px}.links a{text-decoration:none}.btn{display:inline-flex;align-items:center;justify-content:center;gap:14px;min-height:48px;padding:12px 22px;border:1px solid var(--ink);border-radius:10px;background:var(--ink);color:white;text-decoration:none;font-weight:650}.btn.light{background:transparent;color:var(--ink)}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:56px;padding:76px 0 70px}.eyebrow{font-size:11px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;display:flex;align-items:center;gap:9px}.eyebrow:before{content:'';width:7px;height:7px;background:#58793d;border-radius:50%}.hero p{color:var(--muted);font-size:18px;max-width:480px}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:30px 0 15px}.caption{font-size:12px;color:var(--muted)}.visual{background:var(--peach);padding:32px 22px 22px;border-radius:24px;position:relative;min-width:0;transform:rotate(1.5deg)}.visual-label{display:flex;justify-content:space-between;font:11px/1.5 monospace;margin-bottom:20px;letter-spacing:.09em}.studio{background:#fff;border:1px solid #d5c5b6;border-radius:14px;box-shadow:0 20px 50px #47332a17;transform:rotate(-1.5deg);overflow:hidden}.studio-top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding:14px 18px;font-size:12px}.dots{display:flex;gap:4px}.dots i{width:5px;height:5px;border-radius:50%;background:#bdc7b9}.studio-body{display:grid;grid-template-columns:46px 1fr;min-height:300px}.rail{background:#f4f5ef;border-right:1px solid var(--line);display:flex;flex-direction:column;align-items:center;padding:18px 5px;gap:18px}.rail span{width:20px;height:20px;display:grid;place-items:center;color:#7b8574;font:14px monospace}.rail span:first-child{background:var(--accent);border-radius:5px;color:var(--ink)}.preview{padding:22px}.preview small{font-size:11px;color:var(--muted)}.preview h3{font-size:19px;margin:10px 0 15px}.preview-tabs{display:flex;gap:5px;flex-wrap:wrap;margin-bottom:15px}.preview-tabs span{padding:5px 9px;border:1px solid var(--line);border-radius:6px;font-size:10px}.preview-tabs span:first-child{background:var(--accent);border-color:var(--accent)}.sample{border:1px solid var(--line);border-radius:10px;padding:16px;font-size:12px}.sample b{font-size:11px;letter-spacing:.08em}.sample p{margin:8px 0;color:var(--muted)}.sample .line{height:5px;border-radius:3px;background:#e5e9de;margin:9px 0;width:92%}.sample .line:last-child{width:55%}.preview-bottom{display:flex;justify-content:space-between;margin-top:15px;gap:8px;align-items:center}.tag{background:#f0f4e8;border-radius:20px;padding:4px 8px;font-size:10px}.preview-bottom strong{background:var(--ink);color:white;border-radius:6px;padding:7px 11px;font-size:10px}.band{display:flex;justify-content:space-between;gap:22px;flex-wrap:wrap;padding:24px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:12px;letter-spacing:.05em}.band span{color:var(--muted)}section{padding:72px 0}.section-head{display:grid;grid-template-columns:1.2fr 1fr;gap:40px;align-items:end;margin-bottom:32px}.section-head h2{max-width:530px;margin:12px 0 0}.section-head p{margin:0;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}article{border:1px solid var(--line);border-radius:14px;padding:26px;min-width:0;background:#fff}article small{width:34px;height:34px;display:grid;place-items:center;background:var(--accent);border-radius:9px;font:12px monospace;margin-bottom:24px}article p{color:var(--muted);font-size:14px;margin-bottom:0}.workflow{background:var(--ink);color:white;border-radius:22px;padding:40px}.workflow .eyebrow:before{background:var(--accent)}.workflow h2{margin:15px 0 32px}.steps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.step-num{font:12px monospace;color:var(--accent);border-top:1px solid #ffffff30;padding-top:16px;margin-bottom:20px}.steps p{color:#bccabe;font-size:14px}.demo{display:grid;grid-template-columns:.8fr 1.2fr;gap:40px;align-items:start}.demo p{color:var(--muted)}.demo-panel{background:white;border:1px solid var(--line);border-radius:16px;padding:26px}.field{display:block;font-size:12px;font-weight:650;margin-bottom:16px}.field input,.field select{display:block;width:100%;min-height:46px;padding:10px 12px;margin-top:6px;border:1px solid var(--line);border-radius:8px;background:var(--paper);color:var(--ink);min-width:0}.mode-tabs{display:flex;gap:8px;margin:22px 0 12px;flex-wrap:wrap}.mode-tabs button{min-height:40px;border:1px solid var(--line);border-radius:7px;background:white;padding:7px 12px;font-size:12px}.mode-tabs button[aria-selected=true]{background:var(--accent);border-color:var(--accent)}.output{background:#f1f4eb;border-radius:10px;padding:18px;white-space:pre-wrap;font-size:14px;min-height:130px;overflow-wrap:anywhere}.copy{background:none;border:0;font-size:12px;padding:12px 0;color:var(--ink);text-decoration:underline}.faq{border-top:1px solid var(--line);padding:24px 0}.faq summary{cursor:pointer;font-weight:650;list-style:none;display:flex;justify-content:space-between;gap:12px}.faq summary:after{content:'+';font-size:20px}.faq[open] summary:after{content:'−'}.faq p{margin:14px 0 0;max-width:680px;color:var(--muted);font-size:14px}.closing{background:var(--accent);border-radius:22px;text-align:center;padding:48px 22px;margin-bottom:64px}.closing h2{max-width:700px;margin:0 auto 20px}footer{display:flex;justify-content:space-between;gap:24px;flex-wrap:wrap;padding:25px 0;border-top:1px solid var(--line);font-size:12px;color:var(--muted)}#menu{display:none}.hidden{display:none}@media(max-width:850px){.hero{gap:28px}.grid{gap:10px}article{padding:20px}.section-head{gap:24px}.demo{gap:24px}.links{gap:14px}}@media(max-width:680px){.wrap{padding:0 20px}nav{padding:18px 0}.brand{font-size:19px}.links{display:none}.links.open{position:absolute;left:20px;right:20px;top:73px;background:var(--paper);border:1px solid var(--line);border-radius:12px;padding:20px;z-index:5;display:flex;flex-direction:column;align-items:stretch}#menu{display:block;background:none;border:1px solid var(--line);border-radius:8px;min-width:44px;min-height:44px}.hero{grid-template-columns:1fr;padding:40px 0 45px;gap:38px}.hero p{font-size:16px}.visual{padding:22px 14px 14px}.preview{padding:16px}.studio-body{grid-template-columns:34px 1fr}.section-head,.demo{grid-template-columns:1fr;gap:20px}.grid,.steps{grid-template-columns:1fr}section{padding:48px 0}.workflow{padding:28px}.steps{gap:12px}.steps h3{margin-bottom:8px}.band{gap:12px;font-size:10px}.demo-panel{padding:20px}.closing{padding:36px 20px;margin-bottom:40px}footer{gap:10px}.section-head h2{margin-top:10px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
</style></head><body><div class="wrap"><nav><a class="brand" href="#home"><i aria-hidden="true">s</i>__TITLE__</a><button id="menu" aria-label="Buka menu" aria-expanded="false" aria-controls="navigation">☰</button><div class="links" id="navigation"><a href="#fitur">Fitur</a><a href="#alur">Cara kerja</a><a href="#faq">Pertanyaan</a><a href="#demo" class="btn">Coba demo ↗</a></div></nav><main id="home"><header class="hero"><div><span class="eyebrow">Untuk ide yang pantas diwujudkan</span><h1>__HEADLINE__</h1><p>__DESCRIPTION__</p><div class="actions"><a class="btn" href="#demo">Jelajahi demo <span aria-hidden="true">↗</span></a><a class="btn light" href="#fitur">Lihat fitur</a></div><span class="caption">Demo interaktif · Tidak memerlukan akun</span></div><div class="visual"><div class="visual-label"><span>DARI IDE KE KONTEN</span><span>01 / STUDIO</span></div><div class="studio"><div class="studio-top"><b>__TITLE__</b><span class="dots"><i></i><i></i><i></i></span></div><div class="studio-body"><div class="rail" aria-hidden="true"><span>▦</span><span>✎</span><span>⌘</span></div><div class="preview"><small>Workspace / Contoh</small><h3>Ide Anda, lebih terarah.</h3><div class="preview-tabs"><span>Caption</span><span>Ide konten</span><span>Hook</span></div><div class="sample"><b>CONTOH KONTEN</b><p>Cerita sederhana. Produk yang tepat. Alasan untuk memilih Anda.</p><div class="line"></div><div class="line"></div></div><div class="preview-bottom"><span class="tag">Draf untuk ditinjau</span><strong>Siapkan ide ↗</strong></div></div></div></div></div></header><div class="band"><b>RUANG UNTUK BERKARYA.</b><span>Mulai dari kebutuhan Anda</span><span>Susun dengan lebih jelas</span><span>Tinjau sebelum dibagikan</span></div><section id="fitur"><div class="section-head"><div><span class="eyebrow">Yang bisa Anda jelajahi</span><h2>Dari satu ide,<br>jadi langkah berikutnya.</h2></div><p>__DESCRIPTION__</p></div><div class="grid">__CARDS__</div></section><section id="alur"><div class="workflow"><span class="eyebrow">Alur yang mudah diikuti</span><h2>Bukan menambah pekerjaan.<br>Membantu Anda memulainya.</h2><div class="steps"><div><div class="step-num">01 / TENTUKAN</div><h3>Mulai dengan tujuan.</h3><p>Ceritakan produk, audiens, dan pesan yang ingin Anda sampaikan.</p></div><div><div class="step-num">02 / SUSUN</div><h3>Bentuk ide menjadi draf.</h3><p>Pilih format yang sesuai, lalu gunakan contoh sebagai titik awal.</p></div><div><div class="step-num">03 / TINJAU</div><h3>Beri sentuhan Anda.</h3><p>Periksa fakta, sesuaikan suara merek, dan simpan draf yang sudah siap.</p></div></div></div></section><section id="demo" class="demo"><div><span class="eyebrow">Lihat cara kerjanya</span><h2>Coba satu ide<br>sekarang juga.</h2><p>Ubah nama produk dan pilih format. Demo ini menyusun contoh konten secara lokal, tanpa layanan AI yang terhubung.</p><p class="caption">Contoh dapat disalin dan disunting. Selalu tinjau sebelum digunakan.</p></div><div class="demo-panel"><form id="demoForm"><label class="field">Nama produk<input id="product" value="Kopi rumahan" maxlength="80" required></label><label class="field">Untuk siapa?<input id="audience" value="Pencinta kopi" maxlength="100" required></label><button class="btn" type="submit">Buat contoh ↗</button></form><div class="mode-tabs" role="tablist" aria-label="Format konten"><button role="tab" type="button" data-format="caption" aria-selected="true">Caption</button><button role="tab" type="button" data-format="idea" aria-selected="false">Ide konten</button><button role="tab" type="button" data-format="hook" aria-selected="false">Hook</button></div><div id="output" class="output" role="tabpanel" aria-live="polite"></div><button id="copy" class="copy" type="button">Salin contoh</button><span id="copyStatus" class="caption" role="status"></span></div></section><section id="faq"><div class="section-head"><div><span class="eyebrow">Sebelum memulai</span><h2>Ada yang ingin<br>Anda tanyakan?</h2></div><p>Hal-hal yang perlu diketahui tentang contoh halaman ini.</p></div><details class="faq"><summary>Apakah demo ini memakai AI sungguhan?</summary><p>Demo interaktif di halaman ini menggunakan contoh dan logika lokal. Layanan AI perlu dihubungkan ke backend untuk menghasilkan konten model sungguhan.</p></details><details class="faq"><summary>Bisakah contoh konten disunting?</summary><p>Ya. Ubah produk dan audiens, pilih format, lalu salin dan sunting sesuai suara merek Anda. Periksa akurasi sebelum dibagikan.</p></details><details class="faq"><summary>Apakah sudah ada akun atau pembayaran?</summary><p>Belum. Halaman ini adalah prototipe frontend mandiri. Sistem akun, penyimpanan data dan pembayaran memerlukan implementasi backend terpisah.</p></details></section><div class="closing"><span class="eyebrow" style="justify-content:center;margin-bottom:16px">Satu ide cukup untuk memulai</span><h2>Wujudkan langkah berikutnya<br>bersama __TITLE__.</h2><a class="btn" href="#demo">Kembali ke demo ↗</a></div></main><footer><b>__TITLE__</b><span>Prototipe frontend · Contoh konten dapat disunting</span><a href="#home">Kembali ke atas ↑</a></footer></div><script>
(()=>{let mode='caption';const q=id=>document.getElementById(id);function update(){const product=q('product').value.trim()||'produk Anda',audience=q('audience').value.trim()||'audiens Anda';const samples={caption:product+' untuk '+audience+'.\n\nCeritakan apa yang membuat produk Anda berbeda, bagaimana cara menggunakannya, dan alasan yang relevan untuk mencobanya.\n\nTertarik? Tanyakan detail produknya kepada kami.',idea:'Ide konten: cerita di balik '+product+'.\n\n1. Perkenalkan kebutuhan '+audience+'.\n2. Tunjukkan produk dan cara penggunaannya.\n3. Jawab satu pertanyaan yang sering ditanyakan.\n\nSesuaikan semua fakta dengan produk asli Anda.',hook:'Sedang mencari '+product+'?\n\nMulai dari hal yang paling penting untuk '+audience+'.\n\nLanjutkan dengan manfaat yang sudah Anda verifikasi, lalu ajak audiens mengenal produk lebih jauh.'};q('output').textContent=samples[mode];q('copyStatus').textContent=''}q('demoForm').onsubmit=e=>{e.preventDefault();update()};document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{mode=b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));update()});q('copy').onclick=async()=>{try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(q('output').textContent);else{const t=document.createElement('textarea');t.value=q('output').textContent;document.body.append(t);t.select();if(!document.execCommand('copy'))throw Error('copy');t.remove()}q('copyStatus').textContent='Contoh disalin.'}catch(e){q('copyStatus').textContent='Pilih teks contoh untuk menyalin secara manual.'}};q('menu').onclick=()=>{const open=q('navigation').classList.toggle('open');q('menu').setAttribute('aria-expanded',String(open))};q('navigation').querySelectorAll('a').forEach(a=>a.onclick=()=>{q('navigation').classList.remove('open');q('menu').setAttribute('aria-expanded','false')});update()})();
</script></body></html>'''
    return page.replace('__TITLE__', title).replace('__HEADLINE__', headline).replace('__DESCRIPTION__', description).replace('__CARDS__',''.join(cards))
